1	export type Cell = [number, number];
2	
3	const SURVIVAL_NEIGHBOUR_COUNTS = [2, 3];
4	
5	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
6	  x === otherX && y === otherY;
7	
8	const isNeighbour = (cell: Cell, other: Cell): boolean => {
9	  const [x, y] = cell;
10	  const [otherX, otherY] = other;
11	
12	  const isTouching = Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
13	
14	  return isTouching && !isSameCell(cell, other);
15	};
16	
17	const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
18	  liveCells.filter((other) => isNeighbour(cell, other)).length;
19	
20	const BIRTH_NEIGHBOUR_COUNT = 3;
21	
22	const neighboursOf = ([x, y]: Cell): Cell[] =>
23	  [-1, 0, 1].flatMap((dx) =>
24	    [-1, 0, 1]
25	      .filter((dy) => dx !== 0 || dy !== 0)
26	      .map((dy): Cell => [x + dx, y + dy]),
27	  );
28	
29	export function nextGeneration(liveCells: Cell[]): Cell[] {
30	  const survivors = liveCells.filter((cell) =>
31	    SURVIVAL_NEIGHBOUR_COUNTS.includes(countLiveNeighbours(cell, liveCells)),
32	  );
33	
34	  const births = liveCells
35	    .flatMap(neighboursOf)
36	    .filter((cell) => !liveCells.some((live) => isSameCell(cell, live)))
37	    .filter(
38	      (cell) => countLiveNeighbours(cell, liveCells) === BIRTH_NEIGHBOUR_COUNT,
39	    );
40	
41	  return [...survivors, ...births];
42	}
43

