5	  it("returns an empty grid for an empty grid — [] -> []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("kills a single lonely cell — [(0,0)] -> []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("Rule 1 Underpopulation: kills two cells that each have 1 neighbor — [(0,1),(1,1)] -> []", () => {
12	    expect(
13	      nextGeneration([
14	        [0, 1],
15	        [1, 1],
16	      ]),
17	    ).toEqual([]);
18	  });
19	  it("Rule 2 Survival: a live cell with 3 live neighbors lives on — (1,1) survives", () => {
20	    const next = nextGeneration([
21	      [0, 0],
22	      [1, 0],
23	      [2, 0],
24	      [1, 1],
25	    ]);
26	
27	    expect(next).toContainEqual([1, 1]);
