export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) =>
    SURVIVAL_NEIGHBOUR_COUNTS.includes(countLiveNeighbours(cell, liveCells)),
  );

  const births = liveCells
    .flatMap(neighboursOf)
    .filter((cell) => !liveCells.some((live) => isSameCell(cell, live)))
    .filter(
      (cell) => countLiveNeighbours(cell, liveCells) === BIRTH_NEIGHBOUR_COUNT,
    );

  return [...survivors, ...births];
}

input.new_string:
const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
  liveCells.some((live) => isSameCell(cell, live));

const deadNeighboursOf = (liveCells: Cell[]): Cell[] => {
  const candidates = liveCells
    .flatMap(neighboursOf)
    .filter((cell) => !isLive(cell, liveCells));

  return candidates.filter(
    (cell, index) =>
      !candidates.slice(0, index).some((earlier) => isSameCell(cell, earlier)),
  );
};

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) =>
    SURVIVAL_NEIGHBOUR_COUNTS.includes(countLiveNeighbours(cell, liveCells)),
  );

  const births = deadNeighboursOf(liveCells).filter(
    (cell) => countLiveNeighbours(cell, liveCells) === BIRTH_NEIGHBOUR_COUNT,
  );

  return [...survivors, ...births];
}

