const keyOf = ([x, y]: Cell): string => `${x},${y}`;

const uniqueCells = (cells: Cell[]): Cell[] => [
  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
];

const deadNeighboursOf = (liveCells: Cell[]): Cell[] =>
  uniqueCells(
    liveCells.flatMap(neighboursOf).filter((cell) => !isLive(cell, liveCells)),
  );

